import React, { useState, useEffect } from 'react';
import api from '../../services/api';
import { API_ENDPOINTS } from '../../services/apiEndpoints';
import TweetCard from '../tweetCard.tsx';

const TweetList = ({ wallId }) => {
  const [tweets, setTweets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  // Fetch tweets when the component mounts or wallId changes
  useEffect(() => {
    const fetchTweets = async () => {
      try {
        const response = await api.get(API_ENDPOINTS.GET_TWEETS_BY_WALL(wallId));
        setTweets(response.data);
        setLoading(false);
      } catch (err) {
        setError('Failed to load tweets');
        setLoading(false);
      }
    };

    if (wallId) {
      fetchTweets();
    }
  }, [wallId]);

  // Handle randomization of tweets via backend
  const handleRandomize = async () => {
    try {
      const response = await api.patch(API_ENDPOINTS.REORDER_TWEETS(wallId));
      setTweets(response.data);
    } catch (err) {
      setError('Failed to randomize tweets');
    }
  };

  // Handle deletion of a tweet
  const handleDelete = async (tweetId) => {
    if (!window.confirm('Are you sure you want to delete this tweet?')) return;

    try {
      await api.delete(API_ENDPOINTS.DELETE_TWEET(wallId, tweetId));
      setTweets(tweets.filter((tweet) => tweet.id !== tweetId));
    } catch (err) {
      setError('Failed to delete tweet');
    }
  };

  // Loading and error states
  if (loading) return <div className="text-center p-6 text-gray-500">Loading tweets...</div>;
  if (error) return <div className="text-center p-6 text-red-500">{error}</div>;

  return (
    <div className="p-6">
      {/* Randomize button */}
      <div className="flex justify-end mb-4">
        <button
          onClick={handleRandomize}
          className="bg-blue-500 text-white px-4 py-2 rounded hover:bg-blue-600 transition"
          disabled={tweets.length === 0}
        >
          Randomize Tweets
        </button>
      </div>

      {/* Tweet list */}
      {tweets.length === 0 ? (
        <div className="text-center p-6 text-gray-500">No tweets added yet.</div>
      ) : (
        <div className="space-y-4">
          {tweets.map((tweet) => (
            <div
              key={tweet.id}
              className="flex items-center space-x-4 p-4 bg-gray-100 rounded-lg shadow hover:bg-gray-200 transition"
            >
              <TweetCard tweet={tweet} />
              <button
                onClick={() => handleDelete(tweet.id)}
                className="bg-red-500 text-white px-4 py-2 rounded hover:bg-red-600 transition"
              >
                Delete
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default TweetList;
